import{_ as t,o as a,c as n,ag as o}from"./chunks/framework.DaCm-iTo.js";const u=JSON.parse('{"title":"EmakiCooking","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/cooking/index.md","filePath":"en/modules/cooking/index.md","lastUpdated":null}'),i={name:"en/modules/cooking/index.md"};function r(s,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="emakicooking" tabindex="-1">EmakiCooking <a class="header-anchor" href="#emakicooking" aria-label="Permalink to &quot;EmakiCooking&quot;">​</a></h1><p>EmakiCooking runs world-based cooking stations: chopping board, wok, grinder, steamer, oven, juicer, and fermentation barrel. It is separate from equipment progression. Focus on block interaction, coordinate state, ingredient input, staged progress, fluids, and result branches.</p><h2 id="basic-information" tabindex="-1">Basic information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>4.1.5</code></td></tr><tr><td>API jar</td><td><code>emaki-cooking-api-4.1.5.jar</code></td></tr><tr><td>Main class</td><td><code>emaki.jiuwu.craft.cooking.EmakiCookingPlugin</code></td></tr><tr><td>Main command</td><td><code>/ecooking</code></td></tr><tr><td>Alias</td><td><code>/ec</code></td></tr><tr><td>Hard dependency</td><td>EmakiCoreLib</td></tr><tr><td>Soft dependencies</td><td>PlaceholderAPI, CraftEngine, ItemsAdder, Nexo, Oraxen, PacketEvents, MMOItems, NeigeItems</td></tr><tr><td>Minimum server</td><td>Paper 1.21.8+ (<code>api-version: 1.21.8</code>, <code>folia-supported: true</code>)</td></tr><tr><td>Main permissions</td><td><code>emakicooking.use</code> (default true), <code>emakicooking.reload</code> (op), <code>emakicooking.inspect</code> (op), <code>emakicooking.debug</code> (op), <code>emakicooking.admin</code> (op)</td></tr></tbody></table><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands</a></td><td>Reloading station config, inspecting held items and target block sources, rebuilding the station index, and debug.</td></tr><tr><td><a href="./stations.html">Stations</a></td><td>Block sources, progress state, ingredient cache, fuel, fluids, and stage data for the seven station types.</td></tr><tr><td><a href="./recipes.html">Recipes</a></td><td>Per-station recipe fields and interaction differences under <code>recipes/&lt;station&gt;/</code>.</td></tr><tr><td><a href="./nutrition.html">Nutrition</a></td><td>Nutrition accumulation, threshold edge triggers, and persistence.</td></tr><tr><td><a href="./placeholders.html">Placeholders</a></td><td>PlaceholderAPI output.</td></tr><tr><td><a href="./corelib-actions.html">CoreLib Actions</a></td><td>Nutrition value, threshold re-check, and recipe reward actions.</td></tr><tr><td><a href="./api.html">API</a></td><td>The version, plugin name, and readiness probes of <code>EmakiCookingApi</code>.</td></tr><tr><td><a href="./events.html">Event API</a></td><td>Bukkit events across the cooking and nutrition flows.</td></tr></tbody></table><h2 id="seven-station-types" tabindex="-1">Seven station types <a class="header-anchor" href="#seven-station-types" aria-label="Permalink to &quot;Seven station types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Station</th><th>Typical use</th></tr></thead><tbody><tr><td>Chopping Board <code>chopping_board</code></td><td>Cut an ingredient into another form.</td></tr><tr><td>Wok <code>wok</code></td><td>Add ingredients, control heat, stir, and serve.</td></tr><tr><td>Grinder <code>grinder</code></td><td>Grind items into powders or other materials.</td></tr><tr><td>Steamer <code>steamer</code></td><td>GUI/station flow that uses fuel, moisture, and steam progress.</td></tr><tr><td>Oven <code>oven</code></td><td>Add fuel, maintain valid heat, advance baking, and resolve the baking stage.</td></tr><tr><td>Juicer <code>juicer</code></td><td>Press ingredients into fluid and bottle servings by container capacity.</td></tr><tr><td>Fermentation Barrel <code>fermentation_barrel</code></td><td>Insert multiple ingredients, seal and ferment, then collect early, normal, or over-fermented results.</td></tr></tbody></table><h2 id="default-configuration-layout" tabindex="-1">Default configuration layout <a class="header-anchor" href="#default-configuration-layout" aria-label="Permalink to &quot;Default configuration layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiCooking/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── recipes/</span></span>
<span class="line"><span>│   ├── chopping_board/</span></span>
<span class="line"><span>│   ├── wok/</span></span>
<span class="line"><span>│   ├── grinder/</span></span>
<span class="line"><span>│   ├── steamer/</span></span>
<span class="line"><span>│   ├── oven/</span></span>
<span class="line"><span>│   ├── juicer/</span></span>
<span class="line"><span>│   └── fermentation_barrel/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   ├── steamer.yml</span></span>
<span class="line"><span>│   ├── oven.yml</span></span>
<span class="line"><span>│   ├── juicer.yml</span></span>
<span class="line"><span>│   └── fermentation_barrel.yml</span></span>
<span class="line"><span>├── item_adjustments/</span></span>
<span class="line"><span>├── nutrition/</span></span>
<span class="line"><span>├── data/</span></span>
<span class="line"><span>│   ├── stations/</span></span>
<span class="line"><span>│   │   └── index/</span></span>
<span class="line"><span>│   └── stations-legacy-backup/</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>recipes/</code></td><td>Recipes grouped by station. Start with the target station folder.</td></tr><tr><td><code>gui/steamer.yml</code></td><td>Steamer GUI.</td></tr><tr><td><code>gui/oven.yml</code></td><td>Oven GUI.</td></tr><tr><td><code>gui/juicer.yml</code></td><td>Juicer GUI.</td></tr><tr><td><code>gui/fermentation_barrel.yml</code></td><td>Fermentation barrel GUI.</td></tr><tr><td><code>item_adjustments/</code></td><td>Extra adjustments for input or output items.</td></tr><tr><td><code>nutrition/</code></td><td>Nutrition type definitions. Ships with <code>grain.yml</code>, <code>protein.yml</code>, <code>vegetable.yml</code>, <code>fruit.yml</code>, and <code>sugar.yml</code>. See the nutrition documentation.</td></tr><tr><td><code>data/stations/</code></td><td>YAML fallback for stations anchored on normal blocks; block-entity stations prefer block PDC.</td></tr><tr><td><code>data/stations/index/</code></td><td>One <code>&lt;world&gt;.idx</code> per world, recording station coordinates, type, item source, and storage backend for chunk-load recovery.</td></tr><tr><td><code>data/stations-legacy-backup/</code></td><td>Backup directory for legacy YAML states after successful migration to block-entity PDC.</td></tr><tr><td><code>config.yml</code></td><td>Global station recognition, interaction, restriction, display, fuel, and fluid settings.</td></tr></tbody></table><h2 id="world-state-flow" tabindex="-1">World-state flow <a class="header-anchor" href="#world-state-flow" aria-label="Permalink to &quot;World-state flow&quot;">​</a></h2><ol><li>A player interacts with a station block.</li><li>Cooking checks whether the block matches a configured station.</li><li>The state for that world location is loaded.</li><li>The module runs the operation according to the held item, permissions, container, fuel, and recipe.</li><li>Station state is updated, such as input items, cuts, heat, burn time, steam, moisture, fluid amount, or fermentation progress.</li><li>When requirements are met, the module gives results, bottles fluid, advances a stage, or runs actions.</li><li>If the anchor is a block entity, state is written to block PDC and indexed; normal blocks fall back to <code>data/stations/</code> YAML.</li><li>On restart or chunk load, Cooking uses <code>data/stations/index/&lt;world&gt;.idx</code> to locate and restore station state.</li></ol><h2 id="external-block-plugins" tabindex="-1">External block plugins <a class="header-anchor" href="#external-block-plugins" aria-label="Permalink to &quot;External block plugins&quot;">​</a></h2><p>Cooking can recognize custom blocks and items through CraftEngine, ItemsAdder, and Nexo. If those plugins are not installed, the related custom stations do not work, but vanilla block/item setups can still run.</p><p>Display entities are controlled by <code>display_entities.backend</code>:</p><ul><li><code>auto</code>: use virtual display entities through PacketEvents when available, otherwise fall back to Bukkit ItemDisplay.</li><li><code>packet_events</code>: prefer PacketEvents and fall back to Bukkit if loading fails.</li><li><code>bukkit</code>: always use real Bukkit ItemDisplay entities.</li></ul><h2 id="configuration-tips" tabindex="-1">Configuration tips <a class="header-anchor" href="#configuration-tips" aria-label="Permalink to &quot;Configuration tips&quot;">​</a></h2><ul><li>Start with vanilla blocks before connecting CraftEngine / ItemsAdder / Nexo.</li><li>Prefer block-entity anchors for large station counts when IO pressure matters; use <code>/ec inspect block</code> to confirm <code>tile_state=yes</code> and <code>storage_backend=BLOCK_PDC</code>.</li><li>Add one minimal recipe per station first to verify the interaction chain.</li><li>Test persistence after server restart for every stateful station.</li><li>For ovens, test low heat, valid heat, high heat, and overbaking.</li><li>For juicers, test fluid capacity, serving capacity, mixed-fluid protection, and block breaking behavior.</li><li>For fermentation barrels, test early collection, normal completion, over-fermentation, GUI pause behavior, and sealing requirements.</li><li>Focus anti-dupe testing on fast clicking, full inventories, item switching, and block breaking.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="station-not-recognized" tabindex="-1">Station not recognized <a class="header-anchor" href="#station-not-recognized" aria-label="Permalink to &quot;Station not recognized&quot;">​</a></h3><p>Check the block source type, external block plugin, station id, and player permission.</p><h3 id="recipe-does-not-trigger" tabindex="-1">Recipe does not trigger <a class="header-anchor" href="#recipe-does-not-trigger" aria-label="Permalink to &quot;Recipe does not trigger&quot;">​</a></h3><p>Check input item source, amount, station type, current state, container, fuel, and permission.</p><h3 id="oven-does-not-progress" tabindex="-1">Oven does not progress <a class="header-anchor" href="#oven-does-not-progress" aria-label="Permalink to &quot;Oven does not progress&quot;">​</a></h3><p>Check whether the heat is within <code>heat.min</code> and <code>heat.max</code>, whether fuel time remains, and whether <code>bake_time_seconds</code> is valid.</p><h3 id="juicer-cannot-serve" tabindex="-1">Juicer cannot serve <a class="header-anchor" href="#juicer-cannot-serve" aria-label="Permalink to &quot;Juicer cannot serve&quot;">​</a></h3><p>Check whether the current fluid amount reaches <code>serving_ml</code>, whether the player is holding an allowed container, and whether the station already contains another fluid type.</p><h3 id="fermentation-barrel-cannot-collect" tabindex="-1">Fermentation barrel cannot collect <a class="header-anchor" href="#fermentation-barrel-cannot-collect" aria-label="Permalink to &quot;Fermentation barrel cannot collect&quot;">​</a></h3><p>Check fermentation progress, sealing state, early collection ratio, and whether the recipe has already moved into the over-fermented branch.</p><h3 id="state-lost-after-restart" tabindex="-1">State lost after restart <a class="header-anchor" href="#state-lost-after-restart" aria-label="Permalink to &quot;State lost after restart&quot;">​</a></h3><p>Check <code>/ec inspect block</code> for <code>tile_state</code>, <code>storage_backend</code>, <code>pdc_state</code>, <code>indexed</code>, and <code>legacy_yaml</code>. If the coordinate index is stale, run <code>/ec station reindex</code>. For normal-block anchors, also check whether <code>data/stations/</code> is writable and whether YAML files were removed manually.</p>`,32)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
